#!/usr/bin/env bash
# Generates <build>/test/.env (paths + platform facts + app test env) from
# SBT_ENV_JSON and installs executor.sh (as execute_tests.sh) and summary.py
# into <build>/test. The emulator itself lives in <build>/runner.sh + runner.env
# (generated by the builder).
# Required env: SBT_ENV_JSON.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYBIN="${PYTHON_BIN:-python3}"

test_path="$("$PYBIN" "$SCRIPT_DIR/write_env.py" "$SBT_ENV_JSON")"
env_file="$test_path/.env"

cp "$SCRIPT_DIR/executor.sh" "$test_path/execute_tests.sh"
chmod +x "$test_path/execute_tests.sh"
cp "$SCRIPT_DIR/summary.py" "$test_path/summary.py"
rm -rf "$test_path/profiles"
cp -r "$SCRIPT_DIR/profiles" "$test_path/profiles"

printf 'generated test env: %s\n' "$env_file"
printf 'generated test executor: %s\n' "$test_path/execute_tests.sh"
